/* Original SVG artwork used wherever a photograph has not been supplied.
   Four deterministic motifs drawn from the institute's own visual language. */
function ArtTile({ seed = 0, label, className = "" }) {
  const v = Math.abs(seed) % 4;
  const uid = `art${Math.abs(seed)}`;
  return (
    <div className={`relative w-full h-full overflow-hidden ${className}`}>
      <svg viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" className="w-full h-full" aria-hidden="true">
        <defs>
          <linearGradient id={`${uid}bg`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#F2F7FC" />
            <stop offset="100%" stopColor={T.blueSoft} />
          </linearGradient>
        </defs>
        <rect width="400" height="300" fill={`url(#${uid}bg)`} />
        <g fill="none" stroke={T.blue} strokeOpacity="0.34" strokeWidth="1.2">
          {v === 0 && [...Array(9)].map((_, i) => (
            <circle key={i} cx="200" cy="150" r={18 + i * 20} strokeOpacity={0.4 - i * 0.035} />
          ))}
          {v === 1 && (
            <>
              {[...Array(7)].map((_, i) => (
                <line key={i} x1="0" y1={30 + i * 40} x2="400" y2={30 + i * 40} strokeOpacity="0.12" />
              ))}
              <polyline points="0,150 120,150 134,150 146,108 158,196 170,150 250,150 262,128 274,172 286,150 400,150"
                stroke={T.teal} strokeOpacity="0.9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </>
          )}
          {v === 2 && (
            <>
              {[[80,90],[190,60],[300,110],[130,190],[250,200],[340,230],[60,240]].map(([x, y], i, a) =>
                a.slice(i + 1).map(([x2, y2], j) => {
                  const d = Math.hypot(x2 - x, y2 - y);
                  return d < 145 ? <line key={`${i}-${j}`} x1={x} y1={y} x2={x2} y2={y2} strokeOpacity="0.28" /> : null;
                })
              )}
              {[[80,90],[190,60],[300,110],[130,190],[250,200],[340,230],[60,240]].map(([x, y], i) => (
                <circle key={i} cx={x} cy={y} r={i % 3 === 0 ? 9 : 6}
                  fill={i % 3 === 0 ? T.teal : T.blue} fillOpacity="0.5" stroke="none" />
              ))}
            </>
          )}
          {v === 3 && [...Array(6)].map((_, i) => (
            <path key={i} d={`M -20 ${300 - i * 34} Q 200 ${210 - i * 40} 420 ${300 - i * 34}`}
              strokeOpacity={0.42 - i * 0.05} stroke={i % 2 ? T.teal : T.blue} strokeWidth="1.4" />
          ))}
        </g>
      </svg>
      {label && (
        <span className="absolute bottom-3 left-3 text-[10.5px] font-bold uppercase tracking-widest px-2 py-1 rounded-md"
          style={{ background: "rgba(255,255,255,.82)", color: T.muted }}>{label}</span>
      )}
    </div>
  );
}

