function ArticlesPage({ articles, go, openStory, stories }) {
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("All");
  const list = useMemo(() => articles.filter((a) => {
    if (!a.published) return false;
    if (cat !== "All" && a.category !== cat) return false;
    const t = q.trim().toLowerCase();
    return !t || a.title.toLowerCase().includes(t) || a.excerpt.toLowerCase().includes(t);
  }), [articles, q, cat]);

  return (
    <>
      <PageHeader eyebrow="Articles & blog" title="Medical articles and patient education"
        sub="Guidance written for patients on diabetes, thyroid health, hormones and general wellbeing." />
      <section className="py-16 sm:py-20" style={{ background: "#fff" }}>
        <div className="mx-auto max-w-7xl px-5 sm:px-8">
          <div className="flex flex-col lg:flex-row gap-4 lg:items-center justify-between mb-10">
            <div className="relative max-w-sm w-full">
              <Search size={17} color={T.muted} className="absolute left-4 top-1/2 -translate-y-1/2" />
              <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search articles"
                aria-label="Search articles"
                className="w-full rounded-full pl-11 pr-4 py-3 text-sm outline-none"
                style={{ border: `1px solid ${T.line}`, color: T.navy }} />
            </div>
            <div className="flex flex-wrap gap-2">
              {["All", ...CATEGORIES].map((c) => (
                <button key={c} onClick={() => setCat(c)}
                  className="rounded-full px-3.5 py-1.5 text-[12.5px] font-semibold transition-colors"
                  style={{
                    background: cat === c ? T.navy : T.mist,
                    color: cat === c ? "#fff" : T.text,
                    border: `1px solid ${cat === c ? T.navy : T.line}`,
                  }}>{c}</button>
              ))}
            </div>
          </div>

          {list.length === 0 ? (
            <div className="rounded-2xl py-16 text-center" style={{ background: T.mist, border: `1px solid ${T.line}` }}>
              <FileText size={26} color="#A9C3DE" className="mx-auto mb-4" />
              <p className="text-[15px] font-semibold" style={{ color: T.navy }}>No articles match that search</p>
              <p className="text-[14px] mt-2" style={{ color: T.muted }}>Try a different term or clear the category filter.</p>
            </div>
          ) : (
            <div className="grid md:grid-cols-3 gap-6">
              {list.map((a, i) => (
                <Reveal key={a.id} delay={i * 60}>
                  <ArticleCard a={a} go={go} openStory={openStory} stories={stories} />
                </Reveal>
              ))}
            </div>
          )}
        </div>
      </section>
    </>
  );
}

function ArticlePage({ slug, articles, go, openStory, stories = [] }) {
  const a = articles.find((x) => x.slug === slug && x.published);
  if (!a) return (
    <section className="py-24 text-center" style={{ background: "#fff" }}>
      <p className="text-lg font-semibold" style={{ color: T.navy }}>Article not found</p>
      <div className="mt-5"><Btn onClick={() => go("articles")} variant="ghost">Back to all articles</Btn></div>
    </section>
  );
  const related = articles.filter((x) => x.published && x.id !== a.id && x.category === a.category).slice(0, 2);
  const linked = a.storyKey && stories.find((x) => x.key === a.storyKey && x.published);
  const share = typeof window !== "undefined" ? window.location.href : "";

  return (
    <>
      <section className="pt-12 pb-10" style={{ background: T.navy }}>
        <div className="mx-auto max-w-3xl px-5 sm:px-8">
          <button onClick={() => go("articles")} className="inline-flex items-center gap-1.5 text-[13px] font-semibold mb-6"
            style={{ color: "#8FB6E4" }}>
            <ChevronLeft size={15} /> All articles
          </button>
          <span className="inline-block text-[10.5px] font-bold uppercase tracking-widest px-2.5 py-1 rounded-md mb-4"
            style={{ background: "rgba(15,167,154,.15)", color: "#5FD4C7" }}>{a.category}</span>
          <h1 className="text-white font-bold tracking-tight text-[2rem] sm:text-[2.5rem] leading-tight"
            style={{ fontFamily: "var(--display)" }}>{a.title}</h1>
          <p className="mt-4 text-[13.5px]" style={{ color: "#8FA9C6" }}>
            {a.author} · {new Date(a.date).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })}
          </p>
        </div>
      </section>

      <article className="py-14 sm:py-16" style={{ background: "#fff" }}>
        <div className="mx-auto max-w-3xl px-5 sm:px-8">
          <div className="rounded-2xl aspect-[16/8] overflow-hidden mb-10" style={{ border: `1px solid ${T.line}` }}>
            <div className="w-full h-full kb"><ArtTile seed={a.id} /></div>
          </div>
          {linked && (
            <div className="rounded-2xl p-5 mb-9 flex flex-wrap items-center gap-4 justify-between"
              style={{ background: T.mist, border: `1px solid ${T.line}` }}>
              <div>
                <p className="text-[14.5px] font-bold" style={{ color: T.navy, fontFamily: "var(--display)" }}>
                  Explore this topic visually
                </p>
                <p className="text-[13.5px] mt-1" style={{ color: T.muted }}>
                  A short interactive explanation in {linked.steps.length} steps.
                </p>
              </div>
              <Btn onClick={() => openStory(linked.key)} variant="teal" className="!px-5 !py-2.5">
                <Activity size={15} /> Start
              </Btn>
            </div>
          )}
          {a.body.split("\n\n").map((p, i) => (
            <p key={i} className="text-[16.5px] leading-[1.8] mb-6" style={{ color: T.text }}>{p}</p>
          ))}

          <div className="mt-10 pt-8 flex flex-wrap items-center gap-3" style={{ borderTop: `1px solid ${T.line}` }}>
            <span className="text-[12.5px] font-bold uppercase tracking-widest mr-1" style={{ color: T.muted }}>Share</span>
            {[
              ["WhatsApp", `https://wa.me/?text=${encodeURIComponent(a.title + " " + share)}`],
              ["Facebook", `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(share)}`],
              ["X", `https://twitter.com/intent/tweet?text=${encodeURIComponent(a.title)}&url=${encodeURIComponent(share)}`],
            ].map(([n, u]) => (
              <a key={n} href={u} target="_blank" rel="noreferrer"
                className="rounded-full px-4 py-2 text-[13px] font-semibold"
                style={{ border: `1px solid ${T.line}`, color: T.navy }}>{n}</a>
            ))}
          </div>

          <div className="mt-10 rounded-2xl p-7" style={{ background: T.mist, border: `1px solid ${T.line}` }}>
            <h3 className="text-[17px] font-bold mb-2" style={{ color: T.navy, fontFamily: "var(--display)" }}>
              Have a question about your own health?
            </h3>
            <p className="text-[14.5px] leading-relaxed mb-5" style={{ color: T.muted }}>
              This article is general information. For advice about your condition, book a consultation.
            </p>
            <Btn onClick={() => go("appointment")}>Book an Appointment</Btn>
          </div>

          {related.length > 0 && (
            <div className="mt-14">
              <h3 className="text-xl font-bold mb-6" style={{ color: T.navy, fontFamily: "var(--display)" }}>Related articles</h3>
              <div className="grid sm:grid-cols-2 gap-5">
                {related.map((r) => (
                  <ArticleCard key={r.id} a={r} go={go} openStory={openStory} stories={stories} />
                ))}
              </div>
            </div>
          )}
        </div>
      </article>
    </>
  );
}

