function AdminLogin({ onLogin, go }) {
  const [u, setU] = useState(""); const [p, setP] = useState("");
  const [show, setShow] = useState(false); const [e, setE] = useState("");
  const submit = () => {
    if (u === "admin" && p === "clinic2026") { setE(""); onLogin(); }
    else setE("Those credentials are not recognised.");
  };
  return (
    <section className="min-h-screen grid place-items-center px-5 py-16" style={{ background: T.navy }}>
      <div className="w-full max-w-sm">
        <button onClick={() => go("home")} className="inline-flex items-center gap-1.5 text-[13px] font-semibold mb-6"
          style={{ color: "#8FB6E4" }}><ChevronLeft size={15} /> Back to website</button>
        <div className="rounded-2xl p-8" style={{ background: "#fff" }}>
          <span className="grid place-items-center h-11 w-11 rounded-xl mb-5" style={{ background: T.blueSoft }}>
            <Shield size={20} color={T.blue} />
          </span>
          <h1 className="text-2xl font-bold" style={{ color: T.navy, fontFamily: "var(--display)" }}>Admin sign in</h1>
          <p className="text-[13.5px] mt-2 mb-7" style={{ color: T.muted }}>
            Manage the doctor profile, services, articles, gallery and appointment requests.
          </p>
          <div className="space-y-4">
            <Field label="Username">
              <input value={u} onChange={(ev) => setU(ev.target.value)} className={inputCls} style={inputStyle} />
            </Field>
            <Field label="Password">
              <div className="relative">
                <input type={show ? "text" : "password"} value={p} onChange={(ev) => setP(ev.target.value)}
                  onKeyDown={(ev) => ev.key === "Enter" && submit()}
                  className={inputCls} style={{ ...inputStyle, paddingRight: "3rem" }} />
                <button onClick={() => setShow(!show)} aria-label={show ? "Hide password" : "Show password"}
                  className="absolute right-3 top-1/2 -translate-y-1/2" style={{ color: T.muted }}>
                  {show ? <EyeOff size={17} /> : <Eye size={17} />}
                </button>
              </div>
            </Field>
            {e && <p className="text-[13px]" style={{ color: "#DC5B5B" }}>{e}</p>}
            <Btn onClick={submit} className="w-full !py-3.5">Sign in</Btn>
          </div>
          <div className="mt-6 rounded-xl p-4" style={{ background: "#FFF8E7", border: "1px solid #F0DEB0" }}>
            <p className="text-[12.5px] leading-relaxed" style={{ color: "#7A5A08" }}>
              <strong>Prototype only.</strong> This check runs in the browser and secures nothing.
              Demo credentials: <code>admin</code> / <code>clinic2026</code>. Replace with server-side
              authentication before going live.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

